#!/usr/bin/env node
// 公開ドキュメントの sidebar 到達性契約を機械検証するチェッカー（#1727 PR A）。
//
// 背景:
//   sidebars.js は autogenerated を使わない完全手書きのため、載せ忘れたページは
//   ナビゲーションから到達できない。lychee はリンク切れは見るが「未リンク」は
//   見ないので CI も素通りしていた。本 script は「公開対象の日本語ページは
//   sidebar に載っているか、理由付きで未掲載を宣言しているか」を契約として検証する。
//
// 対象の決め方（決定論）:
//   - 分母: pages/**/*.md のうち `.en.md` を除いたもの（日本語ページ）。
//     英語ページは sidebar 掲載の単位が日本語ページと 1:1 対応であり、
//     issue #1727 の実測（101 本）も日本語のみを数えているため対象外とする。
//   - パス segment が `_` で始まるファイル / ディレクトリは除外
//     （Docusaurus docs plugin の既定 exclude と同じ扱い。partials 用）。
//   - frontmatter に `draft: true` または `unlisted: true` を持つページは除外
//     （Docusaurus 側で意図的に隠す仕組みが既にあるため、sidebar 掲載を要求しない）。
//   - doc ID は「pages/ からの相対パス（拡張子なし）」。frontmatter `id` がある
//     場合は最後の segment を置き換える（Docusaurus の ID 解決と同じ規則）。
//
// 未掲載の宣言:
//   意図的に sidebar へ載せないページは SIDEBAR_ALLOWLIST に「doc ID → 理由」で
//   登録する。理由は必須で、空文字はエラーになる（check-doc-enumerations.mjs の
//   ignoreKeys と同じ「理由なしの黙殺を作らない」方針。検証も resolveIgnoreKeys を
//   import して同じ実装を使う）。sidebar に載った・ページが消えた allowlist エントリは
//   期限切れとしてエラーにする（残すと復活時に永久に検査されないため）。
//
// 運用手順は docs/development/sidebar-reachability-check.md を参照。

import fs from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';
import { createRequire } from 'node:module';

import matter from 'gray-matter';

import { isDirectRun } from './lib/is-direct-run.mjs';
// 「理由必須の除外」の検証は check-doc-enumerations.mjs が既に持つ。
// 同じ概念を再実装せず import する（CLAUDE.md「Import the SSoT, never re-derive it」）。
import { resolveIgnoreKeys } from './check-doc-enumerations.mjs';

const ROOT = path.resolve(import.meta.dirname, '..');
const PAGES_DIR = 'pages';
const SIDEBARS_FILE = 'sidebars.js';

/**
 * 意図的に sidebar へ載せないページの allowlist（doc ID → 理由）。
 * 理由は必須。空文字・文字列以外はエラーとして扱われ、除外として採用されない。
 *
 * 仕分け済み（#1727 PR B）: PR A で暫定登録した 48 本を 1 本ずつ読み、37 本を
 * sidebar へ移し、残る 11 本をここに残した。残す基準は「調査・設計の記録」
 * 「他の掲載ページに置き換わった重複」「本リポジトリ限定の開発者向け手順」の
 * いずれかであること。各エントリの理由には、なぜ載せないのかと、利用者向けの
 * 正となる掲載ページを書く。新規に追加するときも同じ粒度で書く。
 */
export const SIDEBAR_ALLOWLIST = {
  'explanation/embedding-code-index-research':
    'embedding-based code index を採用するかの調査記録（#691）。本文が「実装は当面見送り」と宣言する未採用案の記録であり、repo-wide なコンテキスト収集の利用者向け正本は guides/repo-wide-review と explanation/river-architecture が担う',
  'guides/governance/issue-labels':
    'Issue テンプレートとラベル一覧だけを扱う部分集合。sidebar 掲載済みの guides/governance/issue-management が同じテンプレート・type/優先度ラベルに加えて Milestone と依存関係まで含む正本であり、2 本を並べると読者がどちらに従うか判断できない',
  'guides/planner-eval-dataset':
    '本リポジトリの tests/fixtures/planner-dataset/ と npm run planner:eval:dataset を対象にした planner 回帰評価の開発者向け手順。導入側リポジトリでは再現できず、利用者向けのスキル選択の説明は guides/choose-skills と guides/debug-skill-routing が正本',
  'guides/planner-evaluation':
    'npm run planner:eval のメトリクス定義と実行手順。planner を改造する開発者向けで README から辿れる。利用者向けのスキル選択の入口は guides/choose-skills が正本',
  'guides/pr-review-agent-skills':
    '外部公開されている Agent Skills を取り込むか評価するための調査メモで、外部リポジトリのスナップショット。同梱スキルの一覧という利用者向けの正本は reference/skills-catalog',
  'guides/skill-planner':
    'src/lib/review-runner.mjs の planner 差し込み口へ LLM を接続するコード例。この JS API は reference/stable-interfaces が定義する安定契約（CLI / action.yml / skill schema / PR コメント marker）に含まれず、sidebar へ載せると未保証の内部 API を公開契約に見せてしまう',
  'reference/eval-keep-discard-policy':
    '本リポジトリの skill / planner 変更を採否判断するメンテナ向けポリシーで、docs/eval/ の ledger 運用と対になる。評価結果の公開面は sidebar 掲載済みの reference/detector-evaluation-report が担い、そこから本ページへリンクしている',
  'reference/evaluation-fixture-format':
    '本リポジトリの tests/fixtures/review-eval/cases.json と scripts/evaluate-review-fixtures.mjs を前提にした内部評価の入力仕様。入口は sidebar 掲載済みの reference/detector-evaluation-report からのリンクで足りる',
  'reference/evaluation-rubric':
    '多次元スコアリングの仕様。本文が「ランタイム統合は別途追跡中」と宣言しており、未実装の指標を利用者向けリファレンスとして提示すると誤解を招く。実装済みの評価結果は reference/detector-evaluation-report が正本',
  'reference/plangate-cli-roadmap':
    '#802 の契約ドリフト棚卸しと安定化フェーズ計画。現時点の契約ではなく将来計画の記録であり、利用者が従う契約は reference/stable-interfaces と「CLI 仕様」カテゴリの 3 spec が正本',
  'reference/skill-metadata':
    'Issue #68 のメタデータ設計記録。同じフィールド定義は sidebar 掲載済みの reference/skill-schema・reference/skill-schema-reference・reference/metadata-fields が現行版として扱い、実装上の正本は schemas/skill.schema.json',
};

/**
 * ページの相対パスと frontmatter `id` から Docusaurus の doc ID を導出する。
 *
 * @param {string} relPath pages/ からの相対パス（例: `guides/faq.md`）
 * @param {string | undefined} frontmatterId frontmatter の `id`（無ければ undefined）
 * @returns {string} doc ID（例: `guides/faq`）
 */
export function docIdFromPage(relPath, frontmatterId) {
  const posixPath = relPath.split(path.sep).join('/');
  const withoutExt = posixPath.replace(/\.md$/, '');
  if (typeof frontmatterId !== 'string' || frontmatterId.trim() === '') {
    return withoutExt;
  }
  const dir = path.posix.dirname(withoutExt);
  return dir === '.' ? frontmatterId.trim() : `${dir}/${frontmatterId.trim()}`;
}

/** パス segment のどれかが `_` で始まるか（Docusaurus 既定 exclude 相当）。 */
function hasPartialSegment(relPath) {
  return relPath.split(path.sep).some((segment) => segment.startsWith('_'));
}

/**
 * 公開対象の日本語ページを列挙し、doc ID を解決する。
 *
 * @param {string} [pagesDir] repo-relative なページディレクトリ
 * @returns {Promise<{ pages: Array<{ relPath: string, docId: string }>, errors: string[] }>}
 */
export async function listPublishedJaPages(pagesDir = PAGES_DIR) {
  const pages = [];
  const errors = [];
  const files = await fs.readdir(path.join(ROOT, pagesDir), {
    withFileTypes: true,
    recursive: true,
  });
  for (const entry of files) {
    if (!entry.isFile() || !entry.name.endsWith('.md') || entry.name.endsWith('.en.md')) continue;
    const relPath = path.relative(
      path.join(ROOT, pagesDir),
      path.join(entry.parentPath, entry.name)
    );
    if (hasPartialSegment(relPath)) continue;

    let data;
    try {
      data = matter(await fs.readFile(path.join(ROOT, pagesDir, relPath), 'utf8')).data ?? {};
    } catch (err) {
      errors.push(`${pagesDir}/${relPath}: frontmatter を解析できない (${err.message})`);
      continue;
    }
    if (data.draft === true || data.unlisted === true) continue;
    pages.push({ relPath, docId: docIdFromPage(relPath, data.id) });
  }
  pages.sort((a, b) => a.docId.localeCompare(b.docId));
  return { pages, errors };
}

/**
 * sidebar 設定オブジェクトを再帰的に辿り、参照している doc ID を集める。
 * 未知の item 形状は黙って読み飛ばさず throw する（検証の空振り防止）。
 *
 * @param {unknown} sidebars sidebars.js の module.exports
 * @returns {Set<string>}
 */
export function collectSidebarDocIds(sidebars) {
  const ids = new Set();
  const visit = (item) => {
    if (typeof item === 'string') {
      ids.add(item);
      return;
    }
    if (Array.isArray(item)) {
      for (const child of item) visit(child);
      return;
    }
    if (item && typeof item === 'object') {
      if (item.type === 'doc' || item.type === 'ref') {
        ids.add(item.id);
        return;
      }
      if (item.type === 'category') {
        if (item.link?.type === 'doc') ids.add(item.link.id);
        visit(item.items ?? []);
        return;
      }
      if (item.type === 'link' || item.type === 'html') return;
    }
    throw new Error(`sidebars.js に未知の item がある: ${JSON.stringify(item)}`);
  };
  for (const sidebar of Object.values(sidebars ?? {})) visit(sidebar);
  return ids;
}

/** sidebars.js（CommonJS）を読み込む。テストからは差し替えて注入できる。 */
function loadSidebarIdsFromDisk() {
  const require = createRequire(import.meta.url);
  return collectSidebarDocIds(require(path.join(ROOT, SIDEBARS_FILE)));
}

/**
 * 日本語ページ集合と sidebar 掲載集合を突き合わせる。
 *
 * @param {{
 *   pages?: Array<{ relPath: string, docId: string }>,
 *   pageErrors?: string[],
 *   sidebarIds?: Set<string>,
 *   allowlist?: Record<string, string>,
 * }} [options] テスト用の注入口。省略時は実リポジトリを測定する
 * @returns {Promise<{ errors: string[], reachable: number, allowlisted: number }>}
 */
export async function checkSidebarReachability({
  pages,
  pageErrors,
  sidebarIds,
  allowlist = SIDEBAR_ALLOWLIST,
} = {}) {
  const errors = [];
  if (!pages) {
    const listed = await listPublishedJaPages();
    pages = listed.pages;
    pageErrors = listed.errors;
  }
  errors.push(...(pageErrors ?? []));
  sidebarIds ??= loadSidebarIdsFromDisk();

  // 分母・分子が空のまま OK を返さない（glob ミスや読み込み失敗の空振り防止）。
  if (pages.length === 0) {
    errors.push(`${PAGES_DIR}/ に公開対象の日本語ページが 1 件も無い — 列挙条件を確認する`);
  }
  if (sidebarIds.size === 0) {
    errors.push(`${SIDEBARS_FILE} から doc ID を 1 件も抽出できない — 抽出条件を確認する`);
  }

  // 同一 doc ID への衝突（frontmatter id の重複など）は先に落とす。
  const byId = new Map();
  for (const page of pages) {
    if (byId.has(page.docId)) {
      errors.push(
        `doc ID "${page.docId}" が重複している（${byId.get(page.docId)} と ${page.relPath}）`
      );
      continue;
    }
    byId.set(page.docId, page.relPath);
  }

  const { accepted, errors: allowlistErrors } = resolveIgnoreKeys(
    { doc: SIDEBARS_FILE, id: 'sidebar-reachability' },
    allowlist
  );
  // resolveIgnoreKeys のメッセージは `ignoreKeys["..."]` 形式のため、修正対象が
  // 本ファイルの SIDEBAR_ALLOWLIST だと分かる注記を添える（検証ロジックは変えない）。
  errors.push(
    ...allowlistErrors.map(
      (err) => `${err}（修正対象: scripts/check-sidebar-reachability.mjs の SIDEBAR_ALLOWLIST）`
    )
  );

  let reachable = 0;
  let allowlisted = 0;
  for (const [docId, relPath] of byId) {
    const inSidebar = sidebarIds.has(docId);
    const inAllowlist = Object.hasOwn(accepted, docId);
    if (inSidebar && inAllowlist) {
      errors.push(
        `SIDEBAR_ALLOWLIST["${docId}"] は sidebar に掲載済み — 期限切れの除外なので削除する`
      );
    }
    if (inSidebar) {
      reachable += 1;
    } else if (inAllowlist) {
      allowlisted += 1;
    } else {
      errors.push(
        `${PAGES_DIR}/${relPath} (doc ID "${docId}") が ${SIDEBARS_FILE} に載っていない — ` +
          `sidebar へ追加するか、SIDEBAR_ALLOWLIST に理由付きで登録する`
      );
    }
  }

  // ページが消えた・改名された allowlist エントリは期限切れとして落とす。
  for (const docId of Object.keys(accepted)) {
    if (!byId.has(docId)) {
      errors.push(
        `SIDEBAR_ALLOWLIST["${docId}"] は公開対象の日本語ページに存在しない — ` +
          `期限切れの除外なので削除する`
      );
    }
  }

  // sidebar が実在しない doc を参照している場合も報告する（build 失敗より先に原因を示す）。
  for (const id of [...sidebarIds].sort()) {
    if (!byId.has(id)) {
      errors.push(
        `${SIDEBARS_FILE} が "${id}" を挙げているが対応する日本語ページが無い（行を削除するか ID を直す）`
      );
    }
  }

  return { errors, reachable, allowlisted };
}

// CLI entry point
if (isDirectRun(import.meta.url)) {
  checkSidebarReachability()
    .then(({ errors, reachable, allowlisted }) => {
      if (errors.length === 0) {
        console.log(
          `Sidebar reachability: OK (${reachable} page(s) in sidebar, ${allowlisted} allowlisted)`
        );
        return 0;
      }
      console.error(`Sidebar reachability: ${errors.length} error(s) found`);
      for (const err of errors) {
        console.error(`  - ${err}`);
      }
      console.error('');
      console.error('allowlist: scripts/check-sidebar-reachability.mjs (SIDEBAR_ALLOWLIST)');
      console.error('運用: docs/development/sidebar-reachability-check.md');
      return 1;
    })
    .then((code) => {
      if (code !== 0) process.exitCode = code;
    })
    .catch((err) => {
      console.error(`Sidebar reachability check failed: ${err.message}`);
      process.exitCode = 1;
    });
}
